# Recipes are original compositions, all weights are edible ingredient grams.
recipes=[]
def add(slug,name,kind,time,ingredients,steps,output=None,servings=1):
 items=[{'id':k,'g':v,'min':v*.5,'max':v*1.75,'step':.1} for k,v in ingredients]
 recipes.append({'id':'daily-'+slug,'name':name,'slots':['breakfast','snack'] if kind=='breakfast' else ['snack','breakfast'] if kind=='sandwich' else ['lunch','dinner'],'kind':kind,'time':time,'ingredients':items,'steps':steps,'fixedRatios':True,'baseServings':servings,'estimatedYieldGrams':output or round(sum(v for k,v in ingredients)*(.95 if kind in ['salad','sandwich'] else .85)),'yieldNote':'Оценка выхода. Взвесь всю готовую порцию; масло учтено целиком, бульон и соусы не сливаются.','nutritionMethod':'ingredient-calculation','author':'UNVRSL FIT'})
